MAP
    NAME "SS_MAP_JURI_CONSTRUCCIONES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            'ows_title' 'Construcciones'
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_construcciones.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_JURI_CONSTRUCCIONES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION                   
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE POLYGON
        DATA "geometry from construcciones using unique gid using srid=32614"
        CLASS
            NAME "Construcciones"
            STYLE
                OUTLINECOLOR 0 120 120
            END #STYLE
        END #CLASS
        TOLERANCE 10
    END #LAYER
END #MAP